// Late-purchase fines (docs/reglas-negocio.md, RN-3.3 and RN-3.4).
// Fines are only generated by not buying shares on time.

import { diaDelMes, mesesEntre, type FechaISO } from '@/shared/domain/fechas';

// Configurable parameters (docs/reglas-negocio.md, section 10).
export interface ReglasDeMulta {
  diasDeGracia: number;
  multaPorDia: number;
  topeMensual: number;
  multaPorMesCompleto: number;
}

export interface DetalleDeMulta {
  mesesCompletos: number;
  multaMesesCompletos: number;
  multaMesEnCurso: number;
  total: number;
}

// RN-3.4: multa_mes = MIN(MAX(día − gracia, 0) × multa_por_día, tope).
export function multaDelMesEnCurso(dia: number, reglas: ReglasDeMulta): number {
  const diasDeMora = Math.max(dia - reglas.diasDeGracia, 0);
  return Math.min(diasDeMora * reglas.multaPorDia, reglas.topeMensual);
}

// RN-3.4: each full month without a purchase owes the full-month fine, and
// the current month owes the daily fine. `primerMesPendiente` is the first
// month the shareholder has not bought, so purchases made in advance count.
export function calcularMulta(params: {
  primerMesPendiente: FechaISO;
  hoy: FechaISO;
  reglas: ReglasDeMulta;
}): DetalleDeMulta {
  const { primerMesPendiente, hoy, reglas } = params;
  const mesesAtrasados = mesesEntre(primerMesPendiente, hoy);

  if (mesesAtrasados < 0) {
    return { mesesCompletos: 0, multaMesesCompletos: 0, multaMesEnCurso: 0, total: 0 };
  }

  const multaMesesCompletos = mesesAtrasados * reglas.multaPorMesCompleto;
  const multaMesEnCurso = multaDelMesEnCurso(diaDelMes(hoy), reglas);
  return {
    mesesCompletos: mesesAtrasados,
    multaMesesCompletos,
    multaMesEnCurso,
    total: multaMesesCompletos + multaMesEnCurso,
  };
}
